:host {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
}

#favorites-list {
    flex: 1;
    min-height: 0;
    overflow-x: hidden;
    overflow-y: auto;
}

.channel-list {
    overflow-x: hidden;
}

.empty-favorites,
.empty-favorites-hint {
    padding: 16px 24px;
    text-align: center;
}

