1	import {
2	    ChangeDetectionStrategy,
3	    Component,
4	    computed,
5	    DestroyRef,
6	    effect,
7	    inject,
8	    input,
9	    output,
10	    signal,
11	} from '@angular/core';
12	import { MatButtonModule } from '@angular/material/button';
13	import { MatIconModule } from '@angular/material/icon';
14	import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
15	import { isM3uCatchupPlaybackSupported } from 'm3u-utils';
16	import {
17	    matchesOpenLiveCollectionItem,
18	    OpenLiveCollectionItemState,
19	    PORTAL_PLAYER,
20	    ResolvedLiveCollectionDetail,
21	    StreamResolverService,
22	    UnifiedCollectionItem,
23	    UnifiedFavoriteChannel,
24	    UnifiedRecentDataService,
25	} from '@iptvnator/portal/shared/util';
26	import { EpgListComponent } from '@iptvnator/ui/epg';
27	import { GlobalFavoritesListComponent } from '../global-favorites-list/global-favorites-list.component';
28	import {
29	    AudioPlayerComponent,
30	    ArtPlayerComponent,
31	    HtmlVideoPlayerComponent,
32	    VjsPlayerComponent,
33	} from '@iptvnator/ui/playback';
34	import { ResizableDirective } from 'components';
35	import { SettingsStore } from 'services';
36	import { Channel, EpgProgram } from 'shared-interfaces';
37	import { EpgViewComponent } from 'shared-portals';
38	
39	@Component({
40	    selector: 'app-unified-live-tab',
41	    templateUrl: './unified-live-tab.component.html',
42	    styleUrl: './unified-live-tab.component.scss',
43	    changeDetection: ChangeDetectionStrategy.OnPush,
44	    imports: [
45	        AudioPlayerComponent,
46	        ArtPlayerComponent,
47	        EpgListComponent,
48	        EpgViewComponent,
49	        GlobalFavoritesListComponent,
50	        HtmlVideoPlayerComponent,
51	        MatButtonModule,
52	        MatIconModule,
53	        MatProgressSpinnerModule,
54	        ResizableDirective,
55	        VjsPlayerComponent,
56	    ],
57	})
58	export class UnifiedLiveTabComponent {
59	    readonly items = input.required<UnifiedCollectionItem[]>();
60	    readonly mode = input<'favorites' | 'recent'>('favorites');
61	    readonly searchTerm = input('');
62	    readonly autoOpenItem = input<OpenLiveCollectionItemState | null>(null);
63	
64	    readonly removeItem = output<UnifiedCollectionItem>();
65	    readonly reorderItems = output<UnifiedCollectionItem[]>();
66	    readonly itemPlayed = output<UnifiedCollectionItem>();
67	    readonly autoOpenHandled = output<void>();
68	
69	    private readonly streamResolver = inject(StreamResolverService);
70	    private readonly recentData = inject(UnifiedRecentDataService);
71	    private readonly settingsStore = inject(SettingsStore);
72	    private readonly portalPlayer = inject(PORTAL_PLAYER);
73	    private readonly destroyRef = inject(DestroyRef);
74	
75	    readonly player = this.settingsStore.player;
76	    readonly isEmbeddedPlayer = computed(() =>
77	        this.portalPlayer.isEmbeddedPlayer()
78	    );
79	
80	    readonly activeDetail = signal<ResolvedLiveCollectionDetail | null>(null);
81	    readonly activeUid = signal<string | null>(null);
82	    readonly isSelecting = signal(false);
83	    readonly epgMap = signal<Map<string, EpgProgram | null>>(new Map());
84	    readonly progressTick = signal(0);
85	    readonly currentStreamUrl = computed(
86	        () => this.activeDetail()?.playback.streamUrl ?? ''
87	    );
88	    readonly isM3uSelection = computed(
89	        () => this.activeDetail()?.epgMode === 'm3u'
90	    );
91	    readonly currentPortalEpgItems = computed(
92	        () => this.activeDetail()?.epgItems ?? []
93	    );
94	    readonly currentM3uPrograms = computed(() => {
95	        const detail = this.activeDetail();
96	        if (detail?.epgMode !== 'm3u') {
97	            return [];
98	        }
99	
100	        return detail.epgPrograms ?? [];
101	    });
102	    readonly currentM3uChannel = computed(() => {
103	        const detail = this.activeDetail();
104	        if (detail?.epgMode !== 'm3u') {
105	            return null;
106	        }
107	
108	        return detail.channel ?? null;
109	    });
110	    readonly currentM3uArchivePlaybackAvailable = computed(() =>
111	        isM3uCatchupPlaybackSupported(this.currentM3uChannel())
112	    );
113	    readonly activeRadioChannel = computed(() => {
114	        const channel = this.currentM3uChannel();
115	        return channel?.radio === 'true' ? channel : null;
116	    });
117	    readonly isRadioSelection = computed(() => this.activeRadioChannel() !== null);
118	    readonly shouldUseInlinePlayer = computed(() => {
119	        return this.isRadioSelection() || this.isEmbeddedPlayer();
120	    });
121	    readonly layoutClass = computed(() => {
122	        if (this.isRadioSelection()) {
123	            return 'itv-container itv-container--radio';
124	        }
125	
126	        return this.shouldUseInlinePlayer()
127	            ? 'itv-container'
128	            : 'itv-container--external';
129	    });
130	
131	    readonly activeChannelForOverlay = computed((): Channel | undefined => {
132	        const detail = this.activeDetail();
133	        if (!detail) {
134	            return undefined;
135	        }
136	
137	        if (detail.channel) {
138	            return detail.channel;
139	        }
140	
141	        return {
142	            id: this.activeUid() ?? '',
143	            name: detail.playback.title ?? '',
144	            url: detail.playback.streamUrl,
145	            tvg: {
146	                logo: detail.playback.thumbnail ?? '',
147	                id: '',
148	                name: '',
149	                rec: '',
150	                url: '',
151	            },
152	            group: { title: '' },
153	            http: {
154	                referrer: detail.playback.referer ?? '',
155	                'user-agent': detail.playback.userAgent ?? '',
156	                origin: detail.playback.origin ?? '',
157	            },
158	            radio: 'false',
159	            epgParams: '',
160	        } satisfies Channel;
161	    });
162	
163	    readonly channelsForList = computed((): UnifiedFavoriteChannel[] =>
164	        this.items().map((item) => ({
165	            uid: item.uid,
166	            name: item.name,
167	            logo: item.logo ?? null,
168	            sourceType: item.sourceType,
169	            playlistId: item.playlistId,
170	            playlistName: item.playlistName,
171	            streamUrl: item.streamUrl,
172	            xtreamId: item.xtreamId,
173	            tvgId: item.tvgId,
174	            stalkerCmd: item.stalkerCmd,
175	            stalkerPortalUrl: item.stalkerPortalUrl,
176	            stalkerMacAddress: item.stalkerMacAddress,
177	            addedAt: item.addedAt ?? new Date(0).toISOString(),
178	            position: item.position ?? 0,
179	            contentId: item.contentId,
180	        }))
181	    );
182	
183	    private selectionRequestId = 0;
184	
185	    constructor() {
186	        effect(() => {
187	            const items = this.items();
188	            void this.loadEpgMap(items);
189	
190	            const activeUid = this.activeUid();
191	            if (activeUid && !items.some((item) => item.uid === activeUid)) {
192	                this.onClose();
193	            }
194	        });
195	
196	        effect(() => {
197	            const target = this.autoOpenItem();
198	            const items = this.items();
199	            if (!target || items.length === 0) {
200	                return;
201	            }
202	
203	            const matchedItem = items.find((item) =>
204	                matchesOpenLiveCollectionItem(item, target)
205	            );
206	            if (!matchedItem) {
207	                return;
208	            }
209	
210	            if (this.activeUid() === matchedItem.uid) {
211	                if (this.activeDetail()) {
212	                    this.autoOpenHandled.emit();
213	                    return;
214	                }
215	
216	                if (this.isSelecting()) {
217	                    return;
218	                }
219	            }
220	
221	            void this.activateItem(matchedItem, true);
222	        });
223	
224	        const tickInterval = setInterval(
225	            () => this.progressTick.update((tick) => tick + 1),
226	            30_000
227	        );
228	        this.destroyRef.onDestroy(() => clearInterval(tickInterval));
229	    }
230	
231	    async onChannelSelected(channel: UnifiedFavoriteChannel): Promise<void> {
232	        const item = this.items().find(
233	            (candidate) => candidate.uid === channel.uid
234	        );
235	        if (!item) {
236	            return;
237	        }
238	        await this.activateItem(item);
239	    }
240	
241	    onFavoriteToggled(channel: UnifiedFavoriteChannel): void {
242	        const item = this.items().find(
243	            (candidate) => candidate.uid === channel.uid
244	        );
245	        if (item) {
246	            this.removeItem.emit(item);
247	        }
248	    }
249	
250	    onReorder(channels: UnifiedFavoriteChannel[]): void {
251	        const reordered = channels
252	            .map((channel) =>
253	                this.items().find((candidate) => candidate.uid === channel.uid)
254	            )
255	            .filter(Boolean) as UnifiedCollectionItem[];
256	        this.reorderItems.emit(reordered);
257	    }
258	
259	    onClose(): void {
260	        this.selectionRequestId += 1;
261	        this.isSelecting.set(false);
262	        this.activeDetail.set(null);
263	        this.activeUid.set(null);
264	    }
265	
266	    private async loadEpgMap(items: UnifiedCollectionItem[]): Promise<void> {
267	        const epgMap = await this.streamResolver.loadEpgForItems(items);
268	        this.epgMap.set(epgMap);
269	    }
270	
271	    private async activateItem(
272	        item: UnifiedCollectionItem,
273	        isAutoOpen = false
274	    ): Promise<void> {
275	        if (this.activeUid() === item.uid && this.activeDetail()) {
276	            if (isAutoOpen) {
277	                this.autoOpenHandled.emit();
278	            }
279	            return;
280	        }
281	
282	        const requestId = ++this.selectionRequestId;
283	        this.activeUid.set(item.uid);
284	        this.activeDetail.set(null);
285	        this.isSelecting.set(true);
286	
287	        try {
288	            const detail =
289	                item.sourceType === 'm3u'
290	                    ? await this.streamResolver.resolveM3uPlaybackDetail(item)
291	                    : await this.streamResolver.resolveLiveDetail(item);
292	            if (requestId !== this.selectionRequestId) {
293	                return;
294	            }
295	
296	            this.activeDetail.set(detail);
297	
298	            if (detail.epgMode === 'm3u') {
299	                void this.hydrateSelectedM3uPrograms(item, detail, requestId);
300	            }
301	
302	            if (this.shouldOpenExternalPlayback(detail)) {
303	                void this.portalPlayer.openResolvedPlayback(detail.playback);
304	            }
305	
306	            try {
307	                const updatedItem =
308	                    await this.recentData.recordLivePlayback(item);
309	                if (requestId === this.selectionRequestId) {
310	                    this.itemPlayed.emit(updatedItem);
311	                }
312	            } catch {
313	                // Keep playback/EPG visible even if history persistence fails.
314	            }
315	
316	            if (requestId === this.selectionRequestId && isAutoOpen) {
317	                this.autoOpenHandled.emit();
318	            }
319	        } catch {
320	            if (requestId === this.selectionRequestId) {
321	                this.activeDetail.set(null);
322	                this.activeUid.set(null);
323	            }
324	        } finally {
325	            if (requestId === this.selectionRequestId) {
326	                this.isSelecting.set(false);
327	            }
328	        }
329	    }
330	
331	    private shouldOpenExternalPlayback(
332	        detail: ResolvedLiveCollectionDetail
333	    ): boolean {
334	        return !this.isRadioDetail(detail) && !this.portalPlayer.isEmbeddedPlayer();
335	    }
336	
337	    private isRadioDetail(
338	        detail: ResolvedLiveCollectionDetail | null | undefined
339	    ): boolean {
340	        return detail?.epgMode === 'm3u' && detail.channel?.radio === 'true';
341	    }
342	
343	    private async hydrateSelectedM3uPrograms(
344	        item: UnifiedCollectionItem,
345	        detail: ResolvedLiveCollectionDetail,
346	        requestId: number
347	    ): Promise<void> {
348	        if (detail.epgMode !== 'm3u') {
349	            return;
350	        }
351	
352	        const epgPrograms = await this.streamResolver.loadM3uProgramsForItem(
353	            item,
354	            detail.channel
355	        );
356	        if (requestId !== this.selectionRequestId) {
357	            return;
358	        }
359	
360	        this.activeDetail.update((currentDetail) => {
361	            if (!currentDetail || currentDetail.epgMode !== 'm3u') {
362	                return currentDetail;
363	            }
364	
365	            return {
366	                ...currentDetail,
367	                epgPrograms,
368	            };
369	        });
370	    }
371	}
