    flex-shrink: 0;
    position: relative;
    border-right: 1px solid var(--mat-sys-outline-variant);
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.video-player {
    grid-area: video-player;
    min-height: 0;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.video-player--radio {
    position: relative;
    background: var(--mat-sys-surface);
}

.player-toolbar {
    display: flex;
    align-items: center;
