142	        this.renderer.appendChild(handle, handleLine);
143	
144	        // Create grip dots
145	        const gripDots = this.renderer.createElement('div');
146	        this.renderer.addClass(gripDots, 'resize-handle__grip');
147	        for (let i = 0; i < 3; i++) {
148	            const dot = this.renderer.createElement('span');
149	            this.renderer.appendChild(gripDots, dot);
150	        }
151	        this.renderer.appendChild(handle, gripDots);
