154	        this.renderer.listen(handle, 'mousedown', (e: MouseEvent) =>
155	            this.onMouseDown(e)
156	        );
157	
158	        // Touch events for mobile support
159	        this.renderer.listen(handle, 'touchstart', (e: TouchEvent) =>
160	            this.onTouchStart(e)
161	        );
162	
163	        // Append handle to element
164	        this.renderer.appendChild(this.el.nativeElement, handle);
165	    }
166	
167	    private loadPersistedWidth(): void {
168	        const { key, legacyKeys } = this.resolveStorageKey();
169	        let widthToApply = this.defaultWidth();
170	
171	        if (key) {
172	            let stored = localStorage.getItem(key);
173	            let sourceLegacyKey: string | null = null;
174	
175	            if (!stored) {
176	                for (const legacyKey of legacyKeys) {
177	                    const legacyValue = localStorage.getItem(legacyKey);
178	                    if (legacyValue) {
179	                        stored = legacyValue;
180	                        sourceLegacyKey = legacyKey;
181	                        break;
182	                    }
183	                }
184	            }
185	
