@if (activeDetail()) {
    <div [class]="layoutClass()">
        <div
            class="sidebar"
            appResizable
            [minWidth]="250"
            [maxWidth]="600"
            [defaultWidth]="360"
            storageKey="unified-live-tab-sidebar-width"
        >
            <app-global-favorites-list
                [channels]="channelsForList()"
                [epgMap]="epgMap()"
                [progressTick]="progressTick()"
                [activeUid]="activeUid()"
                [searchTermInput]="searchTerm()"
                [draggable]="mode() === 'favorites'"
                (channelSelected)="onChannelSelected($event)"
                (channelsReordered)="onReorder($event)"
                (favoriteToggled)="onFavoriteToggled($event)"
            />
        </div>

        @if (shouldUseInlinePlayer()) {
            <div class="video-player" [class.video-player--radio]="isRadioSelection()">
                @if (isRadioSelection()) {
                    <button
                        mat-icon-button
                        (click)="onClose()"
                        class="radio-close-btn"
                        aria-label="Close player"
                    >
                        <mat-icon>close</mat-icon>
                    </button>

                    <app-audio-player
                        [url]="currentStreamUrl()"
                        [icon]="
                            activeRadioChannel()?.tvg?.logo ??
                            activeDetail()?.playback?.thumbnail ??
                            ''
                        "
                        [channelName]="
                            activeRadioChannel()?.name ||
                            activeDetail()?.playback?.title ||
                            ''
                        "
                    />
                } @else {
                    <div class="player-toolbar">
                        <span class="player-title">{{
                            activeDetail()?.playback?.title
                        }}</span>
                        <button
                            mat-icon-button
                            (click)="onClose()"
                            class="close-btn"
                        >
                            <mat-icon>close</mat-icon>
                        </button>
                    </div>

                    @if (player() === 'videojs') {
                        <app-vjs-player
                            [options]="{
                                sources: [
                                    {
                                        src: currentStreamUrl(),
                                        type: 'application/x-mpegURL',
                                    },
                                ],
                            }"
                            [volume]="1"
                        />
                    }
                    @if (player() === 'html5') {
                        <app-html-video-player
                            [channel]="activeChannelForOverlay()!"
                            [volume]="1"
                            [showCaptions]="false"
                        />
                    }
                    @if (player() === 'artplayer') {
                        <app-art-player
                            [channel]="activeChannelForOverlay()!"
                            [volume]="1"
                            [showCaptions]="false"
                        />
                    }
                }
            </div>
        }

        @if (!isRadioSelection()) {
            <div class="epg">
                @if (!shouldUseInlinePlayer()) {
                    <div class="player-toolbar">
                        <span class="player-title">{{
                            activeDetail()?.playback?.title
                        }}</span>
                        <button
                            mat-icon-button
                            (click)="onClose()"
                            class="close-btn"
                        >
                            <mat-icon>close</mat-icon>
                        </button>
                    </div>
                }
                <div class="epg-content">
                    @if (isM3uSelection()) {
                        <app-epg-list
                            [controlledChannel]="currentM3uChannel()"
                            [controlledPrograms]="currentM3uPrograms()"
                            [archivePlaybackAvailable]="
                                currentM3uArchivePlaybackAvailable()
                            "
                        />
                    } @else {
                        <app-epg-view [epgItems]="currentPortalEpgItems()" />
                    }
                </div>
            </div>
        }
    </div>
} @else {
    <div class="full-list">
        <app-global-favorites-list
            [channels]="channelsForList()"
            [epgMap]="epgMap()"
            [progressTick]="progressTick()"
            [activeUid]="activeUid()"
            [searchTermInput]="searchTerm()"
            [draggable]="mode() === 'favorites'"
            (channelSelected)="onChannelSelected($event)"
            (channelsReordered)="onReorder($event)"
            (favoriteToggled)="onFavoriteToggled($event)"
        />
    </div>
}

