1	import {
2	    Directive,
3	    ElementRef,
4	    Renderer2,
5	    inject,
6	    input,
7	    output,
8	    OnInit,
9	    OnDestroy,
10	    effect,
11	    signal,
12	    AfterViewInit,
13	} from '@angular/core';
14	
15	const SHARED_SIDEBAR_WIDTH_KEY = 'sidebar-width';
16	const SIDEBAR_WIDTH_KEY_ALIASES = new Set([
17	    SHARED_SIDEBAR_WIDTH_KEY,
18	    'downloads-sidebar-width',
19	    'workspace-sources-panel-width',
20	    'workspace-context-panel-width',
21	    'workspace-settings-panel-width',
22	    'workspace-favorites-panel-width',
23	    'iptvnator_video_sidebar_width',
24	]);
25	
26	/**
27	 * ResizableDirective - Makes an element horizontally resizable by dragging its edge.
28	 *
29	 * Usage:
30	 * ```html
31	 * <div appResizable [minWidth]="200" [maxWidth]="600" [storageKey]="'sidebar-width'">
32	 *   Content here
33	 * </div>
34	 * ```
35	 *
36	 * Features:
37	 * - Smooth drag handle with visual feedback
38	 * - Persists width to localStorage
39	 * - Respects min/max width constraints
40	 * - Emits width changes for reactive updates
41	 */
42	@Directive({
43	    selector: '[appResizable]',
44	    standalone: true,
45	})
46	export class ResizableDirective implements OnInit, AfterViewInit, OnDestroy {
47	    /** Minimum width in pixels */
48	    readonly minWidth = input<number>(200);
49	
50	    /** Maximum width in pixels */
51	    readonly maxWidth = input<number>(600);
52	
53	    /** LocalStorage key for persisting width. Defaults to shared sidebar key when omitted. */
54	    readonly storageKey = input<string>('');
55	
56	    /** Default width to use when no stored value exists */
57	    readonly defaultWidth = input<number>(400);
58	
59	    /** Position of the resize handle: 'right' or 'left' */
60	    readonly handlePosition = input<'right' | 'left'>('right');
61	
62	    /** Emits when width changes during resize */
63	    readonly widthChange = output<number>();
64	
65	    /** Emits when resize starts */
66	    readonly resizeStart = output<void>();
67	
68	    /** Emits when resize ends */
69	    readonly resizeEnd = output<number>();
70	
71	    private handleElement: HTMLElement | null = null;
72	    private isResizing = signal(false);
73	    private startX = 0;
74	    private startWidth = 0;
75	    private currentWidth = signal(0);
76	
77	    // Event listener references for cleanup
78	    private boundMouseMove: ((e: MouseEvent) => void) | null = null;
79	    private boundMouseUp: ((e: MouseEvent) => void) | null = null;
80	    private boundTouchMove: ((e: TouchEvent) => void) | null = null;
81	    private boundTouchEnd: ((e: TouchEvent) => void) | null = null;
82	    private readonly el = inject(ElementRef<HTMLElement>);
83	    private readonly renderer = inject(Renderer2);
84	
85	    constructor() {
86	        // Apply resizing class when dragging
87	        effect(() => {
88	            if (this.isResizing()) {
89	                this.renderer.addClass(document.body, 'resizing-active');
90	                this.renderer.addClass(this.el.nativeElement, 'is-resizing');
91	            } else {
92	                this.renderer.removeClass(document.body, 'resizing-active');
93	                this.renderer.removeClass(this.el.nativeElement, 'is-resizing');
94	            }
95	        });
96	    }
97	
98	    ngOnInit(): void {
99	        // Load persisted width FIRST to avoid flash of default width
100	        this.loadPersistedWidth();
101	        this.setupStyles();
102	    }
103	
104	    ngAfterViewInit(): void {
105	        this.createResizeHandle();
106	    }
107	
108	    ngOnDestroy(): void {
109	        this.removeGlobalListeners();
110	        if (this.handleElement) {
111	            this.handleElement.remove();
112	        }
113	    }
114	
115	    private setupStyles(): void {
116	        const el = this.el.nativeElement;
117	
118	        // Ensure the element has position relative for handle positioning
119	        const computedStyle = window.getComputedStyle(el);
120	        if (computedStyle.position === 'static') {
121	            this.renderer.setStyle(el, 'position', 'relative');
122	        }
123	
124	        // Add transition for smooth width changes (only when not dragging)
125	        this.renderer.addClass(el, 'resizable-element');
126	    }
127	
128	    private createResizeHandle(): void {
129	        const handle = this.renderer.createElement('div');
130	        this.handleElement = handle;
131	
132	        // Set up handle classes based on position
133	        this.renderer.addClass(handle, 'resize-handle');
134	        this.renderer.addClass(
135	            handle,
136	            `resize-handle--${this.handlePosition()}`
137	        );
138	
139	        // Create inner visual elements for the handle
140	        const handleLine = this.renderer.createElement('div');
141	        this.renderer.addClass(handleLine, 'resize-handle__line');
142	        this.renderer.appendChild(handle, handleLine);
143	
144	        // Create grip dots
145	        const gripDots = this.renderer.createElement('div');
146	        this.renderer.addClass(gripDots, 'resize-handle__grip');
147	        for (let i = 0; i < 3; i++) {
148	            const dot = this.renderer.createElement('span');
149	            this.renderer.appendChild(gripDots, dot);
150	        }
151	        this.renderer.appendChild(handle, gripDots);
152	
153	        // Mouse events
154	        this.renderer.listen(handle, 'mousedown', (e: MouseEvent) =>
155	            this.onMouseDown(e)
156	        );
157	
158	        // Touch events for mobile support
159	        this.renderer.listen(handle, 'touchstart', (e: TouchEvent) =>
160	            this.onTouchStart(e)
161	        );
162	
163	        // Append handle to element
164	        this.renderer.appendChild(this.el.nativeElement, handle);
165	    }
166	
167	    private loadPersistedWidth(): void {
168	        const { key, legacyKeys } = this.resolveStorageKey();
169	        let widthToApply = this.defaultWidth();
170	
171	        if (key) {
172	            let stored = localStorage.getItem(key);
173	            let sourceLegacyKey: string | null = null;
174	
175	            if (!stored) {
176	                for (const legacyKey of legacyKeys) {
177	                    const legacyValue = localStorage.getItem(legacyKey);
178	                    if (legacyValue) {
179	                        stored = legacyValue;
180	                        sourceLegacyKey = legacyKey;
181	                        break;
182	                    }
183	                }
184	            }
185	
186	            if (stored) {
187	                const width = parseInt(stored, 10);
188	                if (!isNaN(width)) {
189	                    widthToApply = this.clampWidth(width);
190	                    localStorage.setItem(key, widthToApply.toString());
191	                    if (sourceLegacyKey && sourceLegacyKey !== key) {
192	                        localStorage.removeItem(sourceLegacyKey);
193	                    }
194	                }
195	            }
196	        }
197	
198	        // Apply width immediately without transition to avoid flash
199	        this.setWidthImmediate(widthToApply);
200	    }
201	
202	    /** Set width immediately without CSS transition */
203	    private setWidthImmediate(width: number): void {
204	        this.currentWidth.set(width);
205	        // Temporarily disable transition for immediate application
206	        this.renderer.setStyle(this.el.nativeElement, 'transition', 'none');
207	        this.renderer.setStyle(this.el.nativeElement, 'width', `${width}px`);
208	
209	        // Re-enable transition after a frame
210	        requestAnimationFrame(() => {
211	            this.renderer.removeStyle(this.el.nativeElement, 'transition');
212	        });
213	    }
214	
215	    private onMouseDown(e: MouseEvent): void {
216	        e.preventDefault();
217	        e.stopPropagation();
218	
219	        this.startResize(e.clientX);
220	
221	        this.boundMouseMove = (event: MouseEvent) => this.onMouseMove(event);
222	        this.boundMouseUp = () => this.onMouseUp();
223	
224	        document.addEventListener('mousemove', this.boundMouseMove);
225	        document.addEventListener('mouseup', this.boundMouseUp);
226	    }
227	
228	    private onTouchStart(e: TouchEvent): void {
229	        if (e.touches.length !== 1) return;
230	
231	        e.preventDefault();
232	        e.stopPropagation();
233	
234	        this.startResize(e.touches[0].clientX);
235	
236	        this.boundTouchMove = (event: TouchEvent) => this.onTouchMove(event);
237	        this.boundTouchEnd = () => this.onTouchEnd();
238	
239	        document.addEventListener('touchmove', this.boundTouchMove, {
240	            passive: false,
241	        });
242	        document.addEventListener('touchend', this.boundTouchEnd);
