/**
 * FLIP-style anchor: remember where the clicked item sits in the viewport,
 * then after the sidebar transitions from full-width to narrow and container
 * queries reflow the rows, compensate scrollTop so the clicked item stays put.
 */
private captureScrollAnchor(uid: string): () => void {
    const scrollContainer = this.findScrollContainer();
    const clickedEl = this.findItemEl(uid);
    if (!scrollContainer || !clickedEl) {
        return () => undefined;
    }

    const topBefore = clickedEl.getBoundingClientRect().top;

    return () => {
        const adjust = () => {
            const currentEl = this.findItemEl(uid);
            const currentContainer = this.findScrollContainer();
            if (!currentEl || !currentContainer) {
                return;
            }
            const topAfter = currentEl.getBoundingClientRect().top;
            const delta = topAfter - topBefore;
            if (Math.abs(delta) > 0.5) {
                currentContainer.scrollTop += delta;
            }
        };

        // Run after the current macrotask so the layout-switching effect
        // has flushed, then once more after the 150ms width transition.
        requestAnimationFrame(adjust);
        setTimeout(adjust, 200);
    };
}

