  if (!sb) return { error: 'no sidebar' };
  const nav = sb.querySelector('.nav-list');
  nav.scrollTop = 500;
  await new Promise(r => setTimeout(r, 100));

  const targetUid = 'stalker::d46ac735-13d8-414c-9794-b359c37cd7bb::712';
  const target = document.querySelector(\`app-channel-list-item[data-uid='\${targetUid}'] .channel-list-item\`);
