  const widthBefore = sb.getBoundingClientRect().width;
  const scrollBefore = nav.scrollTop;

  const snapshots = [];
  let startTime = performance.now();
  let lastWidth = widthBefore;
  let widthChanges = 0;

  const observer = () => {
    const now = performance.now();
    const el = document.querySelector(\`app-channel-list-item[data-uid='\${targetUid}']\`);
    const curW = sb.getBoundingClientRect().width;
    if (curW !== lastWidth) {
      widthChanges++;
      snapshots.push({ t: Math.round(now - startTime), w: curW, scrollTop: nav.scrollTop, itemTop: el?.getBoundingClientRect().top });
      lastWidth = curW;
    }
    if (now - startTime < 1000) requestAnimationFrame(observer);
