2	// Used by: xtream live-stream-layout, stalker live-stream-layout,
3	//           portal-collection-live-shell
4	//
5	// Include this mixin in a component's SCSS to get the shared flex host+sidebar
6	// skeleton, then add only the component-specific rules underneath.
7	//
8	// Usage (after adding libs/ui/styles to stylePreprocessorOptions.includePaths):
9	//   @use 'portal-layout' as portal;
10	//   @include portal.live-layout;
11	
12	@mixin live-layout {
