14	        display: flex;
15	        flex-direction: row;
16	        overflow: hidden;
17	        height: 100%;
18	        width: 100%;
19	    }
20	
21	    // ─── Sidebar ─────────────────────────────────────────────────────────────
22	    .sidebar {
23	        // Width controlled by the resizable directive at runtime
24	        width: 400px;
25	        min-width: 250px;
