@use '@angular/material' as mat;
@use '../../styles/portal-layout' as portal;

@include portal.live-layout;

// ─── Sidebar panel header ─────────────────────────────────────────────────────
.category-content-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 8px;
    padding: 8px 12px;
    min-height: 48px;
    flex-shrink: 0;
    background: var(--app-widget-header-bg, var(--mat-sys-surface-container-high));
    border-bottom: 1px solid var(--app-separator);
    app-region: drag;

    // Own buttons (direct children scoped to this component)
    button {
        @include mat.form-field-density(-5);
        app-region: no-drag;
    }

    // Projected buttons (liveHeaderActions slot) — view encapsulation
    // prevents the rule above from reaching them, so ng-deep is required.
    ::ng-deep button {
        app-region: no-drag;
    }
}

.category-meta {
    min-width: 0;
    display: flex;
    align-items: baseline;
    gap: 8px;
    flex: 1;
}

// ─── Title + count chip — now aligned with category-content-view ─────────────
.category-title {
    margin: 0;
    font-size: 0.94rem;
    font-weight: 600;
    letter-spacing: -0.01em;
    color: var(--mat-sys-on-surface);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

// Informational badge — primary-tinted pill with definition ring
.category-subtitle {
    white-space: nowrap;
    flex-shrink: 0;
    font-size: 0.70rem;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: capitalize;
    line-height: 1;
    color: var(--mat-sys-primary);
    background: color-mix(in srgb, var(--mat-sys-primary) 10%, var(--mat-sys-surface-container-high));
    padding: 4px 10px;
    border-radius: 999px;
    box-shadow:
        inset 0 0 0 1px color-mix(in srgb, var(--mat-sys-primary) 30%, transparent),
        0 1px 3px rgba(0, 0, 0, 0.18);
}

// ─── EPG controls ─────────────────────────────────────────────────────────────
.loading-indicator {
    display: flex;
    justify-content: center;
    padding: 16px;
}

.load-more-epg {
    display: flex;
    justify-content: center;
    padding: 8px 0;
}

