@use '../../styles/skeleton';

:host {
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow: hidden;
}

.skeleton-list {
    flex: 1;
    overflow: hidden;
}

.skeleton-grid {
    flex: 1;
    overflow: hidden;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(148px, 1fr));
    gap: 16px;
    padding: 16px;
    align-content: start;
}

.collection-header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 16px;
