async onChannelSelected(channel: UnifiedFavoriteChannel): Promise<void> {
    const item = this.items().find(
        (candidate) => candidate.uid === channel.uid
    );
    if (!item) {
        return;
    }

    const restoreAnchor = this.captureScrollAnchor(channel.uid);
    try {
        await this.activateItem(item);
    } finally {
        restoreAnchor();
    }
}

/**
 * FLIP-style anchor: remember where the clicked item sits in the viewport,
 * then after the sidebar collapses from full-width to narrow and container
 * queries reflow the rows, compensate scrollTop so the clicked item stays put.
 */
private captureScrollAnchor(uid: string): () => void {
    const scrollContainer = this.findScrollContainer();
    const clickedEl = this.findItemEl(uid);
    if (!scrollContainer || !clickedEl) {
        return () => undefined;
    }

    const topBefore = clickedEl.getBoundingClientRect().top;

    return () => {
        requestAnimationFrame(() => {
            const currentEl = this.findItemEl(uid);
            const currentContainer = this.findScrollContainer();
            if (!currentEl || !currentContainer) {
                return;
            }
            const topAfter = currentEl.getBoundingClientRect().top;
            const delta = topAfter - topBefore;
            if (Math.abs(delta) > 0.5) {
                currentContainer.scrollTop += delta;
            }
        });
    };
}

private findScrollContainer(): HTMLElement | null {
    return (
        this.sidebarRef()?.nativeElement.querySelector<HTMLElement>(
            '.nav-list'
        ) ?? null
    );
}

private findItemEl(uid: string): HTMLElement | null {
    const host = this.sidebarRef()?.nativeElement;
    if (!host) {
        return null;
    }
    return host.querySelector<HTMLElement>(
        `app-channel-list-item[data-uid="${CSS.escape(uid)}"]`
    );
}

