file.content:
@use '../../styles/skeleton';

:host {
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow: hidden;
}

.skeleton-list {
    flex: 1;
    overflow: hidden;
}

.skeleton-grid {
    flex: 1;
    overflow: hidden;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(148px, 1fr));
    gap: 16px;
    padding: 16px;
    align-content: start;
}

.collection-header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 16px;
    flex-shrink: 0;
    border-bottom: 1px solid var(--mat-sys-outline-variant);
}

.collection-title {
    font-size: 0.94rem;
    font-weight: 600;
    letter-spacing: -0.01em;
    color: var(--mat-sys-on-surface);
    margin-right: auto;
}

.collection-header-toggles {
    display: flex;
    align-items: center;
    gap: 12px;
}

.toggle-placeholder {
    height: 43px;
    width: 120px;
    border-radius: 18px;
    background: color-mix(in srgb, var(--mat-sys-on-surface) 6%, transparent);

    &--scope {
        width: 200px;
    }
}

.content-toggle,
.scope-toggle {
    .toggle-label {
        margin-left: 4px;
        font-size: 0.75rem;
    }

    mat-icon {
        font-size: 18px;
        width: 18px;
        height: 18px;
    }
}

app-unified-live-tab,
app-unified-grid-tab {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
}

.empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 64px 24px;
    flex: 1;
    text-align: center;
    color: var(--mat-sys-on-surface-variant);

    .empty-icon {
        font-size: 56px;
        height: 56px;
        width: 56px;
        margin-bottom: 16px;
        opacity: 0.4;
    }

    .empty-title {
        font-size: 1.05rem;
        font-weight: 520;
        letter-spacing: -0.01em;
        margin: 0;
    }
}

