agent-browser --cdp 9222 eval "
(async () => {
  const tab = document.querySelector('app-unified-live-tab');
  const sb = tab.querySelector('.sidebar');
  const nav = sb.querySelector('.nav-list');
  nav.scrollTop = 500;
  await new Promise(r => setTimeout(r, 100));

  const items = sb.querySelectorAll('app-channel-list-item');
  // Pick an item near the middle of the viewport
  const visibleItems = Array.from(items).filter(el => {
    const r = el.getBoundingClientRect();
    const navR = nav.getBoundingClientRect();
    return r.top >= navR.top && r.bottom <= navR.bottom;
  });
  const target = visibleItems[Math.floor(visibleItems.length / 2)] || items[10];
  const clickable = target.querySelector('.channel-list-item');
  const targetRect = target.getBoundingClientRect();
  const widthBefore = sb.getBoundingClientRect().width;
  const scrollBefore = nav.scrollTop;

  const widths = [];
  let start = performance.now();
  let lastW = widthBefore;
  const monitor = () => {
    const w = sb.getBoundingClientRect().width;
    if (w !== lastW) { widths.push({ t: Math.round(performance.now() - start), w }); lastW = w; }
    if (performance.now() - start < 1500) requestAnimationFrame(monitor);
  };

  clickable.click();
  requestAnimationFrame(monitor);
  await new Promise(r => setTimeout(r, 1600));

  const targetAfter = sb.querySelector(\`app-channel-list-item[data-test-id], app-channel-list-item\`);
  const finalRect = items[Array.from(items).indexOf(target)].getBoundingClientRect();

  return {
    widthBefore,
    widthAfter: sb.getBoundingClientRect().width,
    widthChanges: widths,
    scrollBefore,
    scrollAfter: nav.scrollTop,
    scrollDelta: nav.scrollTop - scrollBefore,
    itemTopBefore: targetRect.top,
    itemTopAfter: finalRect.top,
    drift: Math.abs(finalRect.top - targetRect.top),
    hasPlayer: !!tab.querySelector('.video-player, app-epg-view'),
    hasEmptyState: !!tab.querySelector('app-portal-empty-state')
  };
})()
" 2>&1

